package com.intermarche.backoffice.engine.replenishment;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.order.*;import com.intermarche.backoffice.domain.wms.handling.ReplenishmentOrder;
import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.fieldops.StockCommands;import com.intermarche.backoffice.engine.stock.*;import com.intermarche.backoffice.engine.operator.OperatorFailure;
import jakarta.inject.Inject;import jakarta.annotation.security.RolesAllowed;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import jakarta.ws.rs.core.MediaType;import java.util.*;import java.math.BigDecimal;
/** Delivery discrepancies are explicit observations and decisions, never inventory adjustments. */
@Path("/receipt-discrepancies") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) @RolesAllowed({"ADMIN","MANAGER","PICKER"})
public class ReceiptDiscrepancyResource {
 @Inject ReplenishmentResource replenishments;@Inject StockCommands receipts;@Inject TemporalStockService stocks;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="ReceiptDiscrepancyInput") public static class Input {public Long storeId,orderId,productId,expectedSupplyId;public BigDecimal quantity;public String requestKey,kind,documentReference,comment;}
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="ReceiptDiscrepancyDecision") public static class Decision {public Long storeId,id;public String requestKey,expectedRevision,decision,reason;public ReplenishmentResource.ReceiptLine receipt;}
 private void text(String value,int max,String label){if(value==null||value.isBlank()||value.length()>max)throw new BadRequestException(label);}
 private void writer(Store store){StockAccount.getEntityManager().lock(store,jakarta.persistence.LockModeType.PESSIMISTIC_WRITE);}
 private ReplenishmentOrder order(Store store,Long orderId){var o=ReplenishmentOrder.<ReplenishmentOrder>find("id=?1 and store=?2",orderId,store).firstResult();if(o==null)throw new NotFoundException();if(o.operation!=ReplenishmentOrder.Operation.TRUCK_UNLOADING||o.sourceBuilding!=null)throw new BadRequestException("Un écart fournisseur concerne une arrivée externe depuis un camion");if(Set.of(com.intermarche.backoffice.domain.wms.BaseHandlingOrder.HandlingOrderStatus.CANCELLED,com.intermarche.backoffice.domain.wms.BaseHandlingOrder.HandlingOrderStatus.FAILED).contains(o.status))throw new BadRequestException("Cet ordre est fermé");if(!replenishments.identity.hasRole("MANAGER")&&!replenishments.identity.hasRole("ADMIN")){String actor=replenishments.identity.getPrincipal().getName();if(o.assignee==null||!actor.equals(o.assignee.badgeId)){long own=com.intermarche.backoffice.domain.handling.HandlingExecution.count("handlingOrder=?1 and employee.badgeId=?2",o,actor);if(own==0)throw new ForbiddenException("Mission non affectée à cet employé");}}com.intermarche.backoffice.domain.fieldops.MissionOperationalState.requireActive(o.id);return org.hibernate.Hibernate.unproxy(o,ReplenishmentOrder.class);}
 private String revision(ReceiptDiscrepancy d){return StockTraceLedger.key(d.id,d.version,d.revisionNumber,d.state);}
 private Map<String,Object> view(ReceiptDiscrepancy d){var v=new LinkedHashMap<String,Object>();v.put("id",d.id);v.put("orderId",id(d.handlingOrder));v.put("productId",id(d.product));v.put("name",d.product.name);v.put("ean",d.product.ean);v.put("unit",com.intermarche.backoffice.engine.catalog.ProductInformationService.unit(d.product));v.put("kind",d.kind);v.put("state",d.state);v.put("quantity",d.quantity);v.put("documentReference",d.documentReference);v.put("comment",d.comment);v.put("reportedBy",d.reportedBy);v.put("decidedBy",d.decidedBy);v.put("decisionReason",d.decisionReason);v.put("decidedAt",d.decidedAt);v.put("revision",revision(d));v.put("acceptedSupplyId",d.acceptedSupply==null?null:id(d.acceptedSupply));v.put("canDecide",replenishments.identity.hasRole("MANAGER")||replenishments.identity.hasRole("ADMIN"));return v;}
 @GET @Transactional public Object list(@QueryParam("storeId")Long storeId,@QueryParam("orderId")Long orderId){try{Store store=replenishments.scope(storeId);var order=order(store,orderId);return ReceiptDiscrepancy.<ReceiptDiscrepancy>list("select d from ReceiptDiscrepancy d join fetch d.product where d.handlingOrder=?1 order by d.id desc",order).stream().map(this::view).toList();}catch(RuntimeException e){throw OperatorFailure.safe(e);}}
 @POST @Transactional public Object report(Input r){try{if(r==null)throw new BadRequestException();Store store=replenishments.scope(r.storeId);writer(store);String fingerprint=StockTraceLedger.key("DELIVERY_DISCREPANCY",r);var old=receipts.previous(store,r.requestKey,fingerprint);if(old!=null)return receipts.value(old);var order=order(store,r.orderId);if(!Set.of("SURPLUS","UNEXPECTED").contains(r.kind==null?"":r.kind))throw new BadRequestException("Précisez excédent ou produit inattendu");Product product=Product.findById(r.productId);if(product==null)throw new BadRequestException("Choisissez le produit reçu");if(r.quantity==null||r.quantity.signum()<=0||r.quantity.scale()>6||r.quantity.precision()-r.quantity.scale()>13||product.productType==ProductType.UNIT&&r.quantity.stripTrailingZeros().scale()>0)throw new BadRequestException("Quantité d’écart positive et unité compatible requises");text(r.comment,2000,"Décrivez l’écart observé");if(r.documentReference!=null&&r.documentReference.length()>300)throw new BadRequestException("Référence de document trop longue");ExpectedSupply expected=null;if("SURPLUS".equals(r.kind)){expected=order.supplies.stream().filter(s->Objects.equals(s.id,r.expectedSupplyId)&&id(s.account.product).equals(product.id)).findFirst().orElseThrow(()->new BadRequestException("Choisissez la ligne attendue concernée par l’excédent"));}else if(order.supplies.stream().anyMatch(s->id(s.account.product).equals(product.id)))throw new BadRequestException("Ce produit est attendu : signalez son excédent sur la ligne concernée");
  var d=new ReceiptDiscrepancy();d.store=store;d.handlingOrder=order;d.product=product;d.expectedSupply=expected;d.kind=r.kind;d.quantity=r.quantity;d.documentReference=r.documentReference;d.comment=r.comment;d.reportedBy=replenishments.identity.getPrincipal().getName();d.persistAndFlush();return receipts.record(store,r.requestKey,fingerprint,"DELIVERY_DISCREPANCY",view(d),List.of(com.intermarche.backoffice.engine.operator.OperationQuantities.amount("DELIVERY_OBSERVED",product,d.id,d.quantity)));
 }catch(RuntimeException e){throw OperatorFailure.safe(e);}}
 @POST @Path("/decisions") @RolesAllowed({"ADMIN","MANAGER"}) @Transactional public Object decide(Decision r){try{if(r==null)throw new BadRequestException();Store store=replenishments.scope(r.storeId);writer(store);String fingerprint=StockTraceLedger.key("DELIVERY_DECISION",r);var old=receipts.previous(store,r.requestKey,fingerprint);if(old!=null)return receipts.value(old);ReceiptDiscrepancy d=ReceiptDiscrepancy.find("id=?1 and store=?2",r.id,store).firstResult();if(d==null)throw new NotFoundException();var order=order(store,id(d.handlingOrder));if(!"REPORTED".equals(d.state)||!Objects.equals(r.expectedRevision,revision(d)))throw new OperatorFailure(409,"STALE_DELIVERY_DISCREPANCY","Cet écart a déjà fait l’objet d’une décision. Actualisez.");text(r.reason,2000,"Justifiez l’acceptation ou le refus");if(!Set.of("ACCEPT","REFUSE").contains(r.decision==null?"":r.decision))throw new BadRequestException("Acceptez ou refusez explicitement ces marchandises");
  if("ACCEPT".equals(r.decision)){
   if(r.receipt==null||r.receipt.locationId==null)throw new BadRequestException("Choisissez l’emplacement physique de réception et la traçabilité requise");var location=BaseLocation.<BaseLocation>findById(r.receipt.locationId);if(location==null)throw new BadRequestException("Adresse de réception inconnue");var buildings=BaseLocation.findBuildingsByLocations(List.of(location));if(buildings.size()!=1||!id(buildings.getFirst()).equals(id(order.destinationBuilding)))throw new BadRequestException("Réceptionnez dans le bâtiment d’arrivée de cet ordre");
   var account=stocks.account(store.id,id(d.product));var supply=stocks.planSupply(account.id,"DELIVERY-GAP-"+d.id,null,id(location),d.quantity,DateTimeProvider.now());d.acceptedSupply=supply;order.supplies.add(supply);ReceiptDiscrepancy.getEntityManager().flush();var receipt=new ReplenishmentResource.Receipt();receipt.storeId=store.id;receipt.eventKey=r.requestKey;r.receipt.supplyId=supply.id;r.receipt.quantity=d.quantity;receipt.lines=List.of(r.receipt);replenishments.acceptObservedDiscrepancy(id(order),receipt,d.reportedBy);d.state="ACCEPTED";
  }else d.state="REFUSED";
  d.decidedBy=replenishments.identity.getPrincipal().getName();d.decidedAt=DateTimeProvider.now();d.decisionReason=r.reason;d.revisionNumber++;d.persistAndFlush();return receipts.record(store,r.requestKey,fingerprint,"DELIVERY_DECISION",view(d));
 }catch(RuntimeException e){throw OperatorFailure.safe(e);}}
}
